#include <iostream>
#include <vector>
#include <memory>
#include <string>
#include <iomanip>

// Giao diện trừu tượng thuần túy: CarbonFootprint
class CarbonFootprint {
public:
    virtual ~CarbonFootprint() = default;
    virtual double getCarbonFootprint() const = 0;
    virtual std::string getIdentification() const = 0;
};

// Lớp Building hiện thực giao diện CarbonFootprint
class Building : public CarbonFootprint {
private:
    double squareFootage;
    double electricityKWhPerSqFt;
public:
    Building(double sqFt, double kwh)
        : squareFootage(sqFt), electricityKWhPerSqFt(kwh) {}

    double getCarbonFootprint() const override {
        // Giả định phát thải 0.85 kg CO2 cho mỗi kWh
        return squareFootage * electricityKWhPerSqFt * 0.85;
    }

    std::string getIdentification() const override {
        return "Building [Area: " + std::to_string(static_cast<int>(squareFootage)) + " sq ft]";
    }
};

// Lớp Car hiện thực giao diện CarbonFootprint
class Car : public CarbonFootprint {
private:
    double milesPerYear;
    double fuelEfficiencyMpg;
public:
    Car(double miles, double mpg)
        : milesPerYear(miles), fuelEfficiencyMpg(mpg) {}

    double getCarbonFootprint() const override {
        // 1 gallon xăng tạo ra xấp xỉ 8.89 kg CO2
        return (milesPerYear / fuelEfficiencyMpg) * 8.89;
    }

    std::string getIdentification() const override {
        return "Car [Fuel Efficiency: " + std::to_string(static_cast<int>(fuelEfficiencyMpg)) + " mpg]";
    }
};

// Lớp Bicycle hiện thực giao diện CarbonFootprint
class Bicycle : public CarbonFootprint {
private:
    std::string modelName;
public:
    explicit Bicycle(std::string model) : modelName(std::move(model)) {}

    double getCarbonFootprint() const override {
        return 0.0; // Xe đạp không phát thải khí nhà kính trực tiếp
    }

    std::string getIdentification() const override {
        return "Bicycle [Model: " + modelName + "]";
    }
};

int main() {
    std::vector<std::unique_ptr<CarbonFootprint>> items;
    items.push_back(std::make_unique<Building>(2500.0, 12.0));
    items.push_back(std::make_unique<Car>(12000.0, 28.0));
    items.push_back(std::make_unique<Bicycle>("Touring Eco Pro"));

    std::cout << std::fixed << std::setprecision(2);
    for (const auto& item : items) {
        std::cout << item->getIdentification() << " -> Carbon Footprint: "
                  << item->getCarbonFootprint() << " kg CO2/year\n";
    }

    return 0;
}
